const document = $('Document Extract PDF').first().json;
const validation = $('Validate Project Context').first().json;
const context = $input.first().json;
const pages = Array.isArray(document.pages) ? document.pages : [];

return pages.map((page) => ({
  json: {
    document: {
      file_name: document.file_name ?? 'document.pdf',
      total_pages: document.total_pages ?? pages.length,
      selected_pages: document.selected_pages ?? pages.map((item) => item.page_number),
    },
    project_context: {
      context_id: context.context_id,
      enabled: context.enabled ?? false,
      start_page: document.explanatory_note_context?.start_page ?? null,
      end_page: document.explanatory_note_context?.end_page ?? null,
      pages_count: context.pages_count ?? 0,
      indexed_chunks: context.chunks_count ?? 0,
      vector_size: context.vector_size ?? 0,
      validation,
    },
    page,
  },
}));

const findings = Array.isArray($json.findings) ? $json.findings : [];

return {
  json: {
    findings,
    experience_queries: findings
      .map((finding) => String(finding.experience_query ?? '').trim())
      .filter((query) => query.length > 0),
  },
};

const prepared = $('Prepare Experience Queries').item.json;
const findings = Array.isArray(prepared.findings) ? prepared.findings : [];
const results = Array.isArray($json.results) ? $json.results : [];
const experienceByFinding = {};

for (let index = 0; index < findings.length; index += 1) {
  const finding = findings[index];
  const result = results[index] ?? {};
  experienceByFinding[finding.finding_id] = Array.isArray(result.sources) ? result.sources : [];
}

return { json: { findings, experience_by_finding: experienceByFinding } };

const expanded = $('Expand PDF Pages').item.json;
const understanding = $('Understand Page').item.json;
const queries = $('Build Normative Queries').item.json;
const normative = $('Search Requirements').item.json;
const userPackages = $('Search User Packages').item.json;
const check = $('Check Norms').item.json;
const augmentation = $('Augment Project Context').item.json;
const finalization = $json;

const findings = (finalization.findings ?? []).map((finding) => ({
  ...finding,
  project_context_sources: augmentation.sources ?? [],
}));

return {
  json: {
    document: expanded.document,
    project_context: expanded.project_context,
    page_number: expanded.page.page_number,
    heuristic_page_type: expanded.page.page_type,
    width_points: expanded.page.width_points,
    height_points: expanded.page.height_points,
    extracted_text: expanded.page.text,
    facts: understanding.facts ?? {},
    normative_queries: queries.queries ?? [],
    normative_sources: normative.sources ?? [],
    user_package_sources: userPackages.sources ?? [],
    normative_check: { summary: check.summary ?? '', findings: check.findings ?? [], metrics: check.metrics ?? {} },
    findings,
  },
};

const pageItems = $input.all().map((item) => item.json);
pageItems.sort((left, right) => left.page_number - right.page_number);
const document = pageItems[0]?.document ?? { file_name: 'document.pdf', total_pages: 0, selected_pages: [] };
const context = pageItems[0]?.project_context ?? { enabled: false };
const pages = pageItems.map(({ document: _document, project_context: _context, ...page }) => page);
const findings = pages.flatMap((page) => Array.isArray(page.findings) ? page.findings : []);

return [{
  json: {
    status: 'completed',
    source_mode: 'pdf_only',
    file_name: document.file_name,
    pdf_file_name: document.file_name,
    total_pages: document.total_pages,
    selected_pages: document.selected_pages,
    analyzed_pages: pages.length,
    findings_count: findings.length,
    summary: findings.length ? `Найдено замечаний: ${findings.length}.` : 'Замечания по выбранным листам не найдены.',
    findings,
    pages,
    explanatory_note_context: context,
    pipeline: ['document_extract','explanatory_note_validation','temporary_project_context_index','page_understanding','project_context_retrieval','normative_queries','normative_search','user_package_search','normative_check','experience_search','finalization','project_context_cleanup'],
    limitations: ['Контекст ПЗ и пользовательские пакеты являются контекстом проекта, а не нормативным доказательством.', 'Точное расположение finding на изображении будет добавлено на этапе визуализации.'],
  },
}];

